    code_lines.append("    rSuctionPressure_LL_Trip_bar    : REAL := 1.20;     (* HP Feed Pump Suction Loss Cavitation Trip [bar] *)")
    code_lines.append("    rFeedORP_HH_Trip_mV             : REAL := 280.0;    (* Free Chlorine Oxidant Membrane Degradation Trip [mV] *)")
    code_lines.append("")
    code_lines.append("    (* Auxiliary Calculation & State Registers *)")
    code_lines.append("    rPrevFeedPress_bar              : REAL := 65.0;     (* Prior Execution Scan Voted Feed Pressure [bar] *)")
    code_lines.append("    rCalculated_dP_dt_bars          : REAL := 0.0;      (* Hydraulic Pressure Derivative [bar/s] *)")
    code_lines.append("    rFeedOsmoticCoeff               : REAL := 0.725;    (* Seawater van 't Hoff Osmotic Factor [bar/(g/L)] *)")
    code_lines.append("    rTempCorrectionFactor_TCF       : REAL := 1.0;      (* ASTM D4516 Temperature Correction Factor [-] *)")
    code_lines.append("    rTargetFeedFlow_m3h             : REAL := 4027.8;   (* Nominal Total Feed Flow for 100,000 m3/d Train [m3/h] *)")
    code_lines.append("    rTargetBoosterFlow_m3h          : REAL := 2215.3;   (* Nominal PX Booster Feed Flow [m3/h] *)")
    code_lines.append("    rTargetHpPumpFlow_m3h           : REAL := 1812.5;   (* Nominal Main HP Pump Flow [m3/h] *)")
    code_lines.append("")
    code_lines.append("    (* Internal Iteration Indices *)")
    code_lines.append("    iIter_PGD                       : INT := 1;         (* PGD Optimization Unrolled Loop Counter [-] *)")
    code_lines.append("    iStage_MPC                      : INT := 0;         (* Receding Horizon Stage Index Counter [-] *)")
    code_lines.append("    iRow                            : INT := 1;         (* Matrix Row Vector Index [-] *)")
    code_lines.append("    iCol                            : INT := 1;         (* Matrix Column Vector Index [-] *)")
    code_lines.append("    rTempSum                        : REAL := 0.0;      (* Temporary Floating-Point Dot Product Accumulator [-] *)")
    code_lines.append("    rTempErr                        : REAL := 0.0;      (* Temporary State Error Register [-] *)")
    code_lines.append("    rDeltaU                         : REAL := 0.0;      (* Temporary Control Slew Difference [-] *)")
    code_lines.append("    rMaxDeltaU                      : REAL := 0.0;      (* Temporary Control Slew Constraint Bound [-] *)")
    code_lines.append("END_VAR")
    code_lines.append("")
    
    return "\n".join(code_lines)

